cat > bot.mjs <<'EOF'
// Notification gate. Decides only; never sends.
const NEW_USER_HOURS = 48; // inferred nudges wait this long after the account and the profile both exist

export const REASON_CODES = [
  'requested_ready',
  'reminder_due',
  'nudge_allowed',
  'new_user_grace',
  'daily_nudge_cap_reached',
  'already_delivered',
  'unknown_timezone',
  'unknown_user_dates',
  'unknown_nudge_limit',
  'unknown_origin',
];

const safe = (dir, s) => String(s).replace(/[^A-Za-z0-9_.-]/g, '_');

export async function decide({ user, candidate, now, config }) {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error('STATE_DIR is not set');
  const { mkdirSync } = await import('node:fs');
  mkdirSync(dir, { recursive: true });
  const ms = now instanceof Date ? now.getTime() : new Date(now).getTime();
  const origin = candidate?.origin;
  if (!['requested', 'inferred', 'reminder'].includes(origin)) return { send: false, reasonCode: 'unknown_origin' };

  const idKey = `sent-${safe(dir, candidate.id)}`;
  const deliver = async (code) => {
    if (!(await gkClaim(dir, idKey))) return { send: false, reasonCode: 'already_delivered' };
    return { send: true, reasonCode: code };
  };

  if (origin === 'requested') return deliver('requested_ready');
  if (origin === 'reminder') return deliver('reminder_due');

  // inferred: new-user grace, then per-local-day cap
  const created = Math.max(Date.parse(user?.createdAt), Date.parse(user?.profileCreatedAt));
  if (!Number.isFinite(created) || !Number.isFinite(ms)) return { send: false, reasonCode: 'unknown_user_dates' };
  if (ms - created < NEW_USER_HOURS * 3600e3) return { send: false, reasonCode: 'new_user_grace' };
  if (!gkZoneOk(user?.timezone)) return { send: false, reasonCode: 'unknown_timezone' };
  const cap = config?.dailyNudgeCap;
  if (!Number.isInteger(cap) || cap < 0) return { send: false, reasonCode: 'unknown_nudge_limit' };

  if (!(await gkClaim(dir, idKey))) return { send: false, reasonCode: 'already_delivered' };
  const c = await gkCount(dir, `nudge-${safe(dir, user.id)}-${gkDayKey(ms, user.timezone)}`, cap);
  if (!c.ok) {
    await gkUnclaim(dir, idKey);
    return { send: false, reasonCode: 'daily_nudge_cap_reached' };
  }
  return { send: true, reasonCode: 'nudge_allowed' };
}

EOF
